P[c_knight_dim2]="Full body from the top of the head down to his boots, with empty magenta space above and below: $PE, brown boots, one hand resting on the sword hilt. $SP"
P[c_knight_fat3]="Full body from the top of the head down to his boots, with empty magenta space above and below: $KA, brown boots, holding a small knife topped with a dollop of pate in one hand and a round bread roll in the other hand, mouth open about to eat, eager eyes. $SP"
P[r_kaamelotte]="The hero is exactly the man from the first reference picture, same face, same blond ponytail, same horned iron Viking helmet, same fur-collared studded leather armor, same round wooden shield on his back, same brown kilt and fur-topped boots, same painted style. A medieval castle hall with a big round wooden table covered with ham, sausages, round bread rolls and cheese, plain red banners without writing, torches. Four separate people around the table, from left to right: first the hero, gesturing while explaining something; second $AR, sitting with his chin on his hand, wearing no helmet; third $PE, standing; fourth $KA, sitting, holding a small knife topped with pate in one hand and a bread roll in the other, about to eat. Each person wears only his own clothes. hand-painted 2000s 2D point-and-click adventure game scene, painterly detailed backgrounds like classic adventure games, bold dark outlines, warm saturated colors, humorous storybook fantasy, characters with realistic adult proportions and ironic expressions, wide composition, no logo, no watermark, no frame, no text, no letters"
P[c_knight_fat4]="Full body from the top of the head down to his boots, with empty magenta space above and below: a tall heavy-set adult man about six feet tall with realistic adult proportions and a normal-sized head, $KA, brown boots, holding a small knife in one hand and a round bread roll in the other hand, mouth open about to eat, eager eyes. $SP"
ids=("$@")
for id in $ids; do
  for s in 1 2; do
    if [[ $id == c_* ]]; then out="persos/${id}_$s.png"; else out="${id}_$s.png"; fi
    [ -f "$out" ] && continue
    seed=$(( ${#id} * 1000 + s * 83 + 1313 ))
    if [[ $id == c_* ]]; then flux-image "${P[$id]}" -s 1024x1280 --seed $seed -o "$out" >/dev/null 2>&1
    else flux-image "${P[$id]}" -i hero.png -s 1280x720 --seed $seed -o "$out" >/dev/null 2>&1; fi
    echo "$(date +%H:%M:%S) ok $out"
  done
done
